// packages/lib/src/inventory/tariffs/tariff-note52-actions.ts

/**
 * U.S. note 52 - the per-origin additional duty of headings 9903.05.20-.84
 * (plans/money/tasks/62-note-52.md).
 *
 * `tariff-note52-actions.json` is generated by `packages/lib/scripts/fetch-hts-lists.ts`
 * and checked in. Generated, never edited by hand.
 *
 * ## Why these are generated when `TARIFF_ACTIONS` is hand-kept
 *
 * That file's header calls the hand-kept half "a dozen or two government actions
 * ... genuinely research, small, and where all the editing happens." Note 52 is
 * none of those: it is **86 origins** whose rate is stated per heading in the
 * schedule. It is the same argument that moved Section 301 membership out of the
 * hand-kept half - enumerated in a government document is not research - so it
 * lands here rather than tripling the size of a file meant to be read.
 *
 * ## The two shapes
 *
 * 55 origins carry a flat rate (12.5% or 10%). Five - the EU, Japan, South
 * Korea, Switzerland and Taiwan - instead get TWO headings each, split on the
 * code's own column 1 rate:
 *
 *   9903.05.48  Japan, column 1 >= 12.5 percent ... the duty in the subheading
 *   9903.05.49  Japan, column 1 <  12.5 percent ... 12.5%
 *
 * ✅ Both branches are `max(0, threshold - mfn)`, so they collapse into one
 * action with `rateBasis: 'topUpTo'` and the row written to `tariff_rate` is
 * still an ordinary flat percentage. `resolveTariffRate` learns nothing new.
 * The EU is not a country, so its two headings fan out to all 27 member states -
 * which is why 60 headings become 86 actions.
 *
 * 🛑 **Every action carries `excludedBy: ['232-metal']`**, which is note 52(f):
 * the duties "shall not apply to ... articles of aluminum, of steel or of copper,
 * nor to derivative aluminum or steel articles provided for in headings
 * 9903.82.02 and 9903.82.04-9903.82.26". That carve-out is why the Form 7501
 * behind task 61 shows `9903.05.90` at 0.00%.
 *
 * ⚠️ **`effectiveFrom` is an assumption**, not an extraction - the note carries
 * no date. See the generator's `NOTE_52_EFFECTIVE_FROM`.
 *
 * 🛑 **Never export this module (or the JSON) through `inventory/tariffs/client.ts`.**
 */

import type { StarterAction } from './tariff-starters'

interface RawNote52File {
  fetchedAt: string
  source: string
  actions: Array<Omit<StarterAction, 'steps'> & { key: string; steps: Array<[string, number]> }>
}

let cached: Record<string, StarterAction> | undefined

/**
 * The generated note 52 actions, keyed the way `TARIFF_ACTIONS` is.
 *
 * Lazily imported and memoised for the lifetime of the process - the same
 * argument `loadHtsGeneral` makes.
 */
export async function loadNote52Actions(): Promise<Record<string, StarterAction>> {
  if (!cached) {
    const mod = await import('./tariff-note52-actions.json')
    const data = ((mod as { default?: unknown }).default ?? mod) as RawNote52File
    const out: Record<string, StarterAction> = {}
    for (const { key, ...action } of data.actions) out[key] = action as StarterAction
    cached = out
  }
  return cached
}

/**
 * **Every** action the expander should apply: the hand-kept `TARIFF_ACTIONS`
 * plus the generated note 52 table.
 *
 * 🛑 Production callers of `expandTariffStarter` must pass this as
 * `deps.actions`. Omitting it falls back to the hand-kept half alone, which
 * silently drops note 52's 10-12.5% on every origin - the understatement 29 §3
 * exists to prevent. The three callers that matter are `adoptTariffStarters`,
 * `planTariffResync` and the `purchasing.listTariffStarterChildren` preview.
 */
export async function loadTariffActions(): Promise<Record<string, StarterAction>> {
  const { TARIFF_ACTIONS } = await import('./tariff-starters')
  return { ...TARIFF_ACTIONS, ...(await loadNote52Actions()) }
}
